import{_ as l,C as s,o as r,c as e,j as i,E as o,a as n,a2 as d}from"./chunks/framework.C21TwvGF.js";const p=JSON.parse(`{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/10-sinf-devops/"},"n":3,"bob":"II-bob · Git va versiya boshqaruvi","lessons":[{"g":7,"title":"Git branchlar va masofaviy repozitoriylar (GitHub, Push, Pull, Merge)","lead":"Jamoaviy dasturlash san'ati: parallel rivojlanish tarmoqlari (branches), birlashtirish (merge), ziddiyatlarni yechish hamda GitHub orqali masofaviy hamkorlik.","link":"/10-sinf-devops/hafta-03/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-1-test.html"},{"g":8,"title":"Kompyuter tarmoqlari asoslari: OSI 7 qatlamli modeli va TCP/IP steki","lead":"Internet qanday ishlaydi: LAN va WAN tarmoqlari, OSI 7 qatlamli etalon modeli, amaliy TCP/IP steki va ma'lumotlar sayohati (enkapsulyatsiya).","link":"/10-sinf-devops/hafta-03/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-2-test.html"},{"g":9,"title":"IP manzillash, Subnetting va tarmoq diagnostikasi vositalari","lead":"Tarmoq muhandisligi asoslari: IPv4 va IPv6, qism tarmoqlarni hisoblash (Subnetting, CIDR) hamda nosozliklarni aniqlovchi qurollar (ping, traceroute, ss, curl).","link":"/10-sinf-devops/hafta-03/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-03/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-devops/hafta-03/index.md","filePath":"10-sinf-devops/hafta-03/index.md"}`),h={name:"10-sinf-devops/hafta-03/index.md"},m={class:"blk"},g={id:"uyga-vazifa",tabindex:"-1"};function c(f,a,u,v,q,y){const t=s("Icon");return r(),e("div",null,[i("div",m,[i("h2",g,[o(t,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>3-haftada Git versiya boshqaruvi tizimining ilg&#39;or mexanizmlari (tarmoqlanish, birlashtirish, ziddiyatlarni hal qilish va masofaviy repozitoriyalar) hamda kompyuter tarmoqlarining fundamental asoslari (OSI modeli, TCP/IP steki, IP manzillash, Subnetting va tarmoq diagnostikasi) o&#39;rganildi. Quyidagi amaliy topshiriqlar bilimlarni sinovdan o&#39;tkazishga qaratilgan.</p><hr><h3 id="_7-dars-vazifasi-git-branchlar-va-birlashtirish" tabindex="-1">7-dars vazifasi: Git Branchlar va Birlashtirish <a class="header-anchor" href="#_7-dars-vazifasi-git-branchlar-va-birlashtirish" aria-label="Permalink to &quot;7-dars vazifasi: Git Branchlar va Birlashtirish&quot;">​</a></h3><ol><li>O&#39;tgan haftadagi <code>my_git_lab</code> repozitoriyasida <code>feature-auth</code> nomli yangi branch oching (<code>git switch -c feature-auth</code>).</li><li>Yangi branch ichida <code>auth.py</code> faylini yaratib, ichiga oddiy login kodini yozing va <code>git commit -m &quot;feat: login funksiyasi qo&#39;shildi&quot;</code> bilan commit qiling.</li><li>Asosiy <code>main</code> branchga qayting (<code>git switch main</code>).</li><li><code>feature-auth</code> branchini <code>main</code> ga birlashtiring (<code>git merge feature-auth</code>).</li><li>Birlashtirilgan branchni xavfsiz o&#39;chiring (<code>git branch -d feature-auth</code>).</li><li><code>git log --oneline --graph</code> buyrug&#39;i natijasini daftaringizga qayd eting. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_8-dars-vazifasi-tarmoq-qatlamlari-va-interfeyslar-tahlili" tabindex="-1">8-dars vazifasi: Tarmoq qatlamlari va Interfeyslar tahlili <a class="header-anchor" href="#_8-dars-vazifasi-tarmoq-qatlamlari-va-interfeyslar-tahlili" aria-label="Permalink to &quot;8-dars vazifasi: Tarmoq qatlamlari va Interfeyslar tahlili&quot;">​</a></h3><ol><li>Linux terminalida <code>ip a</code> buyrug&#39;ini ishga tushiring. Tizimingizdagi jismoniy tarmoq kartasining nomi, uning MAC manzili va lokal IP manzilini aniqlab daftaringizga ko&#39;chirib yozing.</li><li><code>ip route</code> buyrug&#39;i yordamida tashqi dunyoga chiquvchi Default Gateway (Router) IP manzilini toping.</li><li>OSI 7 qatlamli modelining har bir qatlami nomini (1 dan 7 gacha) va har bir qatlamda ishlovchi kamida bittadan protokolni jadval ko&#39;rinishida daftaringizga chizing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_9-dars-vazifasi-subnetting-va-tarmoq-diagnostikasi" tabindex="-1">9-dars vazifasi: Subnetting va Tarmoq diagnostikasi <a class="header-anchor" href="#_9-dars-vazifasi-subnetting-va-tarmoq-diagnostikasi" aria-label="Permalink to &quot;9-dars vazifasi: Subnetting va Tarmoq diagnostikasi&quot;">​</a></h3><ol><li><code>ping -c 4 8.8.8.8</code> buyrug&#39;i orqali Google DNS serveriga so&#39;rov yuboring. O&#39;rtacha kechikish (rtt avg) va paketlar yo&#39;qolish foizini daftaringizga qayd eting.</li><li><code>curl ifconfig.me</code> buyrug&#39;i yordamida uyingizning tashqi ommaviy (Public) IP manzilini aniqlang.</li><li><code>curl -I https://yandex.uz</code> buyrug&#39;ini berib, HTTP javob kodini aniqlang.</li><li>Quyidagi hisoblash masalasini yeching: <ul><li>Berilgan: <code>192.168.100.0/25</code> tarmog&#39;i.</li><li>Aniqlang: a) Tarmoq maskasi (Subnet Mask) b) Foydalanish mumkin bo&#39;lgan maksimal xostlar soni c) Tarmoq manzili (Network ID) d) Efir manzili (Broadcast ID) <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ul></li></ol><hr>',11))])])}const z=l(h,[["render",c]]);export{p as __pageData,z as default};
